#include <iostream>
#include <string>
using namespace std;

int main() {
    try {
        throw string("{msg}");
    } catch (const string& e) {
        cout << "接到一串字：" << e << endl;
    } catch (...) {
        cout << "不管是什么，先接住再说喵" << endl;
    }
    return 0;
}
